import{_ as t,o,c as a,a2 as d}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Package Extraction Readiness","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-table/package-extraction.md","filePath":"dynamic-table/package-extraction.md"}'),r={name:"dynamic-table/package-extraction.md"};function c(i,e,n,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="package-extraction-readiness" tabindex="-1">Package Extraction Readiness <a class="header-anchor" href="#package-extraction-readiness" aria-label="Permalink to &quot;Package Extraction Readiness&quot;">​</a></h1><p>This engine was built inside <code>app/</code> deliberately, with extraction boundaries in mind, but it has <strong>not</strong> been extracted into a standalone Composer package. This page tracks what&#39;s already package-ready and what would need to change before extraction.</p><h2 id="already-package-ready" tabindex="-1">Already package-ready <a class="header-anchor" href="#already-package-ready" aria-label="Permalink to &quot;Already package-ready&quot;">​</a></h2><ul><li><strong><code>Core</code> layer</strong> (<code>app/Support/DynamicTable/Core/</code>): zero imports of <code>Modules\\*</code> or any concrete application Eloquent model. Verified structurally — see <code>tests/</code> (no <code>Modules</code> reference exists in this namespace) and enforced by convention, not yet by an automated architecture test (see &quot;Remaining blockers&quot; below).</li><li><strong><code>Query</code> layer</strong> (<code>app/Support/DynamicTable/Query/</code>): depends only on <code>Core</code> and Eloquent — no Livewire, no Flux, no application models.</li><li><strong>Storage behind contracts</strong>: <code>TablePreferenceStore</code> and <code>SavedTableViewStore</code> are interfaces in <code>Core</code>; the Eloquent implementations live in <code>app/Support/DynamicTable/PreferenceStores/</code> and are bound via <code>AppServiceProvider</code>, not hard-coded into <code>Table</code>.</li><li><strong>Rendering separated from query logic</strong>: <code>Table</code> (Livewire) and the Blade views depend on <code>Core</code>/<code>Query</code>, never the reverse.</li><li><strong>No <code>env()</code> usage</strong> — the little configuration that exists (per-page allowlist, max search length) lives as constants on <code>TableState</code>, not scattered <code>env()</code> calls.</li></ul><h2 id="remaining-application-dependencies-extraction-blockers" tabindex="-1">Remaining application dependencies (extraction blockers) <a class="header-anchor" href="#remaining-application-dependencies-extraction-blockers" aria-label="Permalink to &quot;Remaining application dependencies (extraction blockers)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Blocker</th><th>Where</th><th>Effort to fix</th></tr></thead><tbody><tr><td><code>EloquentTablePreferenceStore</code>/<code>EloquentSavedTableViewStore</code> depend on <code>App\\Models\\User</code>-shaped <code>Authenticatable</code>, and the migrations live in the app&#39;s own <code>database/migrations/</code></td><td><code>app/Support/DynamicTable/PreferenceStores/</code>, <code>database/migrations/2026_08_14_16*</code>, <code>2026_08_14_17*</code></td><td>Low — already behind contracts; a package would ship these as default implementations with publishable migrations</td></tr><tr><td><code>AppServiceProvider</code> manually binds both contracts</td><td><code>app/Providers/AppServiceProvider.php</code></td><td>Low — becomes the package&#39;s own service provider</td></tr><tr><td>No dedicated config file yet — <code>PER_PAGE_OPTIONS</code>, <code>MAX_SEARCH_LENGTH</code>, <code>MAX_MULTI_SELECT</code> are <code>TableState</code> constants</td><td><code>Core/TableState.php</code></td><td>Low-medium — move to a <code>config/dynamic-table.php</code> published by the package provider</td></tr><tr><td>No translation file — labels/messages are inline strings/<code>__()</code> calls scattered through Blade views</td><td><code>resources/views/components/dynamic-table/*.blade.php</code></td><td>Medium — extract to <code>lang/vendor/dynamic-table/*.php</code></td></tr><tr><td>Views live in the app&#39;s own <code>resources/views/</code></td><td><code>resources/views/livewire/dynamic-table/</code>, <code>resources/views/components/dynamic-table/</code></td><td>Low — package would publish these, app overrides via Laravel&#39;s standard view-override mechanism</td></tr><tr><td>Eager loads not select-narrowed per relation (payload bloat, not correctness)</td><td><code>TableQueryBuilder::applyEagerLoads()</code></td><td>Medium — needs per-relation-type introspection to narrow <code>select()</code> inside <code>with()</code></td></tr><tr><td>Relation sort limited to <code>BelongsTo</code> + aggregated to-many; no <code>HasOne</code>, no multi-level paths</td><td><code>TableQueryBuilder::applyRelationSort()</code></td><td>Medium-high — needs a general relation-path walker</td></tr><tr><td>Cursor pagination unimplemented</td><td><code>TableQueryBuilder</code></td><td>Medium</td></tr><tr><td><code>exportable()</code> is a flag with no exporter</td><td><code>Core/Column.php</code></td><td>Medium-high (a full export milestone)</td></tr><tr><td>No row/bulk action framework</td><td>—</td><td>Medium-high</td></tr><tr><td>No summaries (count/sum/avg/min/max)</td><td>—</td><td>Medium</td></tr></tbody></table><p><strong>Resolved since the original version of this table</strong> (kept as a record, not a current blocker): <code>ComputedColumn</code>&#39;s fluent-order dependency was fixed via <code>Column::validate()</code> (order-independent now); a <code>SearchDriver</code> contract with <code>DatabaseSearchDriver</code>/<code>ScoutSearchDriver</code> exists; an architecture test suite now enforces the Core/Query namespace boundaries (<code>tests/Feature/DynamicTable/ArchitectureTest.php</code>); the <code>BelongsToFilter</code> UI is a real debounced async picker, not a plain ID input.</p><h2 id="if-extraction-happens" tabindex="-1">If extraction happens <a class="header-anchor" href="#if-extraction-happens" aria-label="Permalink to &quot;If extraction happens&quot;">​</a></h2><ol><li>Create a new Composer package repo (<code>vendor/dynamic-table</code>), move <code>Core</code>/<code>Query</code>/<code>PreferenceStores</code> verbatim (already dependency-clean).</li><li>Write a <code>DynamicTableServiceProvider</code> that: binds the two store contracts, publishes migrations, publishes views under a <code>dynamic-table::</code> namespace, publishes a config file, registers translations.</li><li>Update this app&#39;s <code>app/Livewire/DynamicTable/*</code> and views to <code>use Vendor\\DynamicTable\\...</code> instead of <code>App\\Support\\DynamicTable\\...</code> — a mechanical namespace change since the app already only depends on <code>Core</code>/<code>Query</code>&#39;s public API.</li><li>Add the architecture test from the table above before/during extraction so the boundary is enforced going forward, not just by convention.</li><li>Publish to Packagist (or a private repo) and add it as a real Composer dependency; run this app&#39;s full <code>DynamicTable</code> test suite against the extracted package as a smoke test.</li></ol><p>None of this is required for the engine to work correctly inside this application today — it&#39;s a forward-looking checklist for the day extraction is actually needed.</p>',10)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
